import React from "react";

function Post3() {
  return (
    <div className="content">
      <h2>Career Skills</h2>
      <p>
        Students can prepare for their careers by developing
        technical, communication and problem-solving skills.
      </p>
      <p>Practice projects and teamwork help build confidence.</p>
    </div>
  );
}

export default Post3;
